export interface AssamDistrictMapProps {
  districtsWithStats: Array<{
    slug: string;
    attractionCount: number;
    institutionCount: number;
  }>;
  selectedDivision?: string;
  onSelectDivision?: (division: string) => void;
}

export const AssamDistrictMap: React.FC<AssamDistrictMapProps> = ({
  districtsWithStats,
  selectedDivision = 'all',
  onSelectDivision,
}) => {
  const { language, t } = useLanguage();
  const dt = t.districts;
  const navigate = useNavigate();

  const [hoveredDistrict, setHoveredDistrict] = useState<DistrictMapData | null>(null);
  const [selectedDistrict, setSelectedDistrict] = useState<DistrictMapData | null>(null);

  // Map verified counts onto district atlas entries
  const mapData = useMemo(() => {
    const statsLookup = new Map<string, { attractions: number; institutions: number }>();
    districtsWithStats.forEach((d) => {
      statsLookup.set(d.slug.toLowerCase(), {
        attractions: d.attractionCount,
        institutions: d.institutionCount,
      });
    });

    return ASSAM_DISTRICT_MAP_ENTRIES.map((item) => {
      const stats = statsLookup.get(item.slug.toLowerCase()) || { attractions: 0, institutions: 0 };
      return {
        ...item,
        attractionCount: stats.attractions,
        institutionCount: stats.institutions,
      };
    });
  }, [districtsWithStats]);

  const activeDistrict = selectedDistrict || hoveredDistrict;

  const handleDistrictClick = (district: DistrictMapData) => {
    setSelectedDistrict(district);
  };

  const handleGoToDistrict = (slug: string) => {
    navigate(`/districts/${slug}`);
  };

  const getDivisionLabel = (val: string): string => {
    switch (val) {
      case 'all': return dt.allRegions;
      case 'Upper Assam': return dt.upperAssam;
      case 'Lower Assam': return dt.lowerAssam;
      case 'Lower Assam (BTR)': return dt.bodoland;
      case 'North Assam': return dt.northAssam;
      case 'Central Assam': return dt.centralAssam;
      case 'Central Assam / Hills': return dt.hillsKarbi;
      case 'Barak Valley': return dt.barakValley;
      default: return val;
    }
  };

  // Division filter categories matching official Assam admin structure
  const divisions = [
    { label: dt.allRegions, value: 'all', color: '#DC2626' },
    { label: dt.upperAssam, value: 'Upper Assam', color: '#059669' },
    { label: dt.lowerAssam, value: 'Lower Assam', color: '#EF4444' },
    { label: dt.bodoland, value: 'Lower Assam (BTR)', color: '#6366F1' },
    { label: dt.northAssam, value: 'North Assam', color: '#0D9488' },
    { label: dt.centralAssam, value: 'Central Assam', color: '#D97706' },
    { label: dt.hillsKarbi, value: 'Central Assam / Hills', color: '#16A34A' },
    { label: dt.barakValley, value: 'Barak Valley', color: '#8B5CF6' },
  ];

  return (
    <div className="assam-interactive-map-card">
      {/* Top Header & Division Filtering Pills */}
      <div className="assam-map-header">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="assam-map-tag">
              <Sparkles size={13} />
              <span>
                {language === 'as'
                  ? 'পাৰস্পৰিক মানচিত্ৰ'
                  : language === 'hi'
                  ? 'इंटरैक्टिव मानचित्र'
                  : language === 'brx'
                  ? 'आरोबाव नुथाय मानचित्रा'
                  : 'Interactive Visual Map'}
              </span>
            </span>
            <span className="assam-map-count-badge">
              {language === 'as' ? '৩৫ খন জিলা' : language === 'hi' ? '३५ जिले' : '35 Districts'}
            </span>
          </div>
          <h2 className="assam-map-title">
            {language === 'as'
              ? 'অসমৰ ভৌগোলিক প্ৰশাসনিক মানচিত্ৰ'
              : language === 'hi'
              ? 'असम का भौगोलिक प्रशासनिक मानचित्र'
              : language === 'brx'
              ? 'आसामनि भुमखौरां प्रसासनिक मानचित्रा'
              : 'Interactive Map of Assam'}
          </h2>
          <p className="assam-map-subtitle">
            {language === 'as'
              ? 'ব্ৰহ্মপুত্ৰ আৰু বৰাক উপত্যকাৰ প্ৰতিখন জিলাৰ সীমাৱদ্ধ ৰূপ দৰ্শন কৰক, পৰিদৰ্শনৰ স্থান আৰু প্ৰশাসনিক তথ্য চাওক।'
              : language === 'hi'
              ? 'असम के सभी ३५ प्रशासनिक जिलों का सीमांकित मानचित्र देखें, दर्शनीय स्थल और प्रशासनिक जानकारी प्राप्त करें।'
              : language === 'brx'
              ? 'ब्रह्मपुत्र आरो बराक हायेननि गासै ३५ जिल्लानि सिमा नुथाय, नायदिंनाय जायगा आरो प्रसासनिक खौरां नाय।'
              : 'Seamless contiguous atlas map of all 35 administrative districts. Hover or tap to inspect verified heritage spots, colleges, headquarters, and portal links.'}
          </p>
        </div>

        {/* Division Selector Pills */}
        <div className="assam-map-division-pills" role="tablist" aria-label="Assam regions">
          {divisions.map((div) => {
            const isSelected = selectedDivision === div.value;
            return (
              <button
                key={div.value}
                type="button"
                className={`assam-map-div-pill ${isSelected ? 'active' : ''}`}
                style={{
                  borderColor: isSelected ? div.color : undefined,
                  background: isSelected ? div.color : undefined,
                  color: isSelected ? '#FFFFFF' : undefined,
                }}
                onClick={() => onSelectDivision && onSelectDivision(div.value)}
              >
                {div.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* SVG Canvas & Interactive Detail Overlay */}
      <div className="assam-map-canvas-container">
        <svg
          viewBox="0 0 1020 620"
          className="assam-map-svg"
          xmlns="http://www.w3.org/2000/svg"
          role="img"
          aria-label="Contiguous Atlas Map of the 35 Districts of Assam"
        >
          <defs>
            {/* Shimmering River Gradient for The Mighty Brahmaputra */}
            <linearGradient id="brahmaputraGrad" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#38BDF8" stopOpacity="0.95" />
              <stop offset="50%" stopColor="#0284C7" stopOpacity="1" />
              <stop offset="100%" stopColor="#0369A1" stopOpacity="0.95" />
            </linearGradient>

            {/* Barak River Gradient */}
            <linearGradient id="barakGrad" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#818CF8" stopOpacity="0.95" />
              <stop offset="100%" stopColor="#6366F1" stopOpacity="0.95" />
            </linearGradient>

            {/* River Glow Filter */}
            <filter id="riverGlow" x="-10%" y="-10%" width="120%" height="120%">
              <feDropShadow dx="0" dy="2" stdDeviation="3" floodColor="#0284C7" floodOpacity="0.45" />
            </filter>

            {/* District Elevation Filter */}
            <filter id="districtShadow" x="-10%" y="-10%" width="120%" height="120%">
              <feDropShadow dx="0" dy="2" stdDeviation="2" floodOpacity="0.12" />
            </filter>
            <filter id="activeDistrictGlow" x="-20%" y="-20%" width="140%" height="140%">
              <feDropShadow dx="0" dy="4" stdDeviation="7" floodColor="#DC2626" floodOpacity="0.55" />
            </filter>
          </defs>

          {/* Background Map Frame with Subtle Topographic Tone */}
          <rect width="1020" height="620" rx="16" fill="#F8FAFC" />

          {/* Compass Rose (North Arrow in Top-Right) */}
          <g transform="translate(970, 45)" opacity="0.8">
            <circle cx="0" cy="0" r="18" fill="#FFFFFF" stroke="#CBD5E1" strokeWidth="1.5" />
            <polygon points="0,-14 5,0 0,-2 -5,0" fill="#DC2626" />
            <polygon points="0,14 5,0 0,2 -5,0" fill="#64748B" />
            <text x="0" y="-18" fontSize="10" fontWeight="900" fill="#DC2626" textAnchor="middle">N</text>
          </g>

          {/* 1. Render All 35 Contiguous District Polygons */}
          <g id="districts-layer">
            {mapData.map((d) => {
              const isHighlighted = activeDistrict?.slug === d.slug;
              const isMatchingDivision =
                selectedDivision === 'all' || d.division === selectedDivision;

              return (
                <path
                  key={d.slug}
                  d={d.path}
                  className={`district-path ${isHighlighted ? 'active' : ''} ${!isMatchingDivision ? 'dimmed' : ''}`}
                  fill={isHighlighted ? '#DC2626' : d.color}
                  stroke={isHighlighted ? '#FFFFFF' : '#FFFFFF'}
                  strokeWidth={isHighlighted ? '2.5' : '1.8'}
                  strokeLinejoin="round"
                  filter={isHighlighted ? 'url(#activeDistrictGlow)' : 'url(#districtShadow)'}
                  opacity={isMatchingDivision ? (isHighlighted ? 1 : 0.92) : 0.28}
                  onMouseEnter={() => setHoveredDistrict(d)}
                  onMouseLeave={() => setHoveredDistrict(null)}
                  onClick={() => handleDistrictClick(d)}
                  tabIndex={0}
                  role="button"
                  aria-label={`${d.name} (${d.name_as})`}
                  style={{
                    cursor: 'pointer',
                    transition: 'all 0.22s cubic-bezier(0.16, 1, 0.3, 1)',
                  }}
                />
              );
            })}
          </g>

          {/* 2. The Mighty Brahmaputra River (Natural flowing valley corridor) */}
          <g id="brahmaputra-river" pointerEvents="none">
            {/* North Channel around Majuli Island (Kherkutia Xuti) */}
            <path
              d="M 740,152 Q 710,156 678,172"
              fill="none"
              stroke="url(#brahmaputraGrad)"
              strokeWidth="4"
              strokeLinecap="round"
              strokeLinejoin="round"
              filter="url(#riverGlow)"
              opacity="0.85"
            />

            {/* Main Brahmaputra Stream */}
            <path
              d="M 915,65 Q 835,95 780,125 T 725,175 Q 675,198 625,212 T 550,224 T 475,246 T 395,272 T 330,290 T 240,298 T 170,310 T 115,330 Q 95,355 88,385"
              fill="none"
              stroke="url(#brahmaputraGrad)"
              strokeWidth="9"
              strokeLinecap="round"
              strokeLinejoin="round"
              filter="url(#riverGlow)"
              opacity="0.92"
            />
            {/* Flow wave highlights */}
            <path
              d="M 915,65 Q 835,95 780,125 T 725,175 Q 675,198 625,212 T 550,224 T 475,246 T 395,272 T 330,290 T 240,298 T 170,310 T 115,330 Q 95,355 88,385"
              fill="none"
              stroke="#E0F2FE"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeDasharray="14 10"
              opacity="0.85"
            />

            {/* Brahmaputra River Watermark Label */}
            <text
              x="550"
              y="220"
              fill="#FFFFFF"
              fontSize="8.5"
              fontWeight="900"
              letterSpacing="2"
              opacity="0.95"
              filter="url(#districtShadow)"
            >
              BRAHMAPUTRA RIVER (ব্ৰহ্মপুত্ৰ)
            </text>
          </g>

          {/* 3. The Barak River (Flowing through Southern Assam) */}
          <g id="barak-river" pointerEvents="none">
            <path
              d="M 560,498 Q 515,508 470,518 T 415,525"
              fill="none"
              stroke="url(#barakGrad)"
              strokeWidth="5"
              strokeLinecap="round"
              strokeLinejoin="round"
              filter="url(#riverGlow)"
              opacity="0.85"
            />
            <path
              d="M 560,498 Q 515,508 470,518 T 415,525"
              fill="none"
              stroke="#EEF2FF"
              strokeWidth="1.6"
              strokeLinecap="round"
              strokeDasharray="8 6"
              opacity="0.8"
            />
            <text
              x="485"
              y="514"
              fill="#FFFFFF"
              fontSize="7.5"
              fontWeight="800"
              letterSpacing="1.5"
              opacity="0.95"
              filter="url(#districtShadow)"
            >
              BARAK RIVER (বৰাক নদী)
            </text>
          </g>

          {/* 4. District Centroid Labels & Interactive Pin Markers */}
          <g id="labels-layer" pointerEvents="none">
            {mapData.map((d) => {
              const isHighlighted = activeDistrict?.slug === d.slug;
              const isMatchingDivision =
                selectedDivision === 'all' || d.division === selectedDivision;
              const labelText = d.shortName || d.name;

              return (
                <g
                  key={`label-${d.slug}`}
                  transform={`translate(${d.cx}, ${d.cy})`}
                  opacity={isMatchingDivision ? 1 : 0.22}
                  style={{
                    transition: 'all 0.2s cubic-bezier(0.16, 1, 0.3, 1)',
                  }}
                >
                  {/* Subtle Pin Dot with Glow */}
                  <circle
                    cx="0"
                    cy="-6"
                    r={isHighlighted ? "4.5" : "2.5"}
                    fill="#FFFFFF"
                    stroke={isHighlighted ? "#DC2626" : d.accentColor}
                    strokeWidth={isHighlighted ? "2" : "1.2"}
                  />

                  {/* Clean SVG Text with Halo (Zero Overlap Clash) */}
                  <text
                    x="0"
                    y="7"
                    textAnchor="middle"
                    fill={isHighlighted ? "#DC2626" : "#0F172A"}
                    stroke="#FFFFFF"
                    strokeWidth={isHighlighted ? "3" : "2.2"}
                    strokeLinejoin="round"
                    paintOrder="stroke fill"
                    fontSize={isHighlighted ? "11.5" : "8.5"}
                    fontWeight={isHighlighted ? "900" : "800"}
                    letterSpacing="0.01em"
                  >
                    {labelText}
                  </text>

                  {/* Assamese Subscript Name (on highlighted active district) */}
                  {isHighlighted && (
                    <text
                      x="0"
                      y="18"
                      textAnchor="middle"
                      fill="#DC2626"
                      stroke="#FFFFFF"
                      strokeWidth="2.5"
                      strokeLinejoin="round"
                      paintOrder="stroke fill"
                      fontSize="9.5"
                      fontWeight="800"
                    >
                      {d.name_as}
                    </text>
                  )}
                </g>
              );
            })}
          </g>
        </svg>

        {/* Live Floating / Pinned District Inspector Card */}
        {activeDistrict && (
          <div className="assam-map-inspect-card">
            <button
              type="button"
              className="assam-inspect-close"
              onClick={() => {
                setSelectedDistrict(null);
                setHoveredDistrict(null);
              }}
              title="Close card"
            >
              <X size={15} />
            </button>

            <div className="assam-inspect-header">
              <span
                className="assam-inspect-division-badge"
                style={{ background: activeDistrict.color, color: '#FFFFFF' }}
              >
                {getDivisionLabel(activeDistrict.division)}
              </span>
              <div className="assam-inspect-hq">
                <MapPin size={12} color="#DC2626" />
                <span>{dt.headquarters}: <strong>{activeDistrict.headquarters}</strong></span>
              </div>
            </div>

            <h3 className="assam-inspect-name">
              {language === 'as' ? activeDistrict.name_as : activeDistrict.name}
              <span className="assam-inspect-name-as">
                ({language === 'as' ? activeDistrict.name : activeDistrict.name_as})
              </span>
            </h3>

            {/* Quick Stats Grid */}
            <div className="assam-inspect-stats-row">
              <div className="assam-inspect-stat">
                <Compass size={14} color="#DC2626" />
                <span><strong>{activeDistrict.attractionCount || 0}</strong> {dt.attractions}</span>
              </div>
              <div className="assam-inspect-stat">
                <GraduationCap size={14} color="#2563EB" />
                <span><strong>{activeDistrict.institutionCount || 0}</strong> {dt.institutions}</span>
              </div>
            </div>

            <button
              type="button"
              onClick={() => handleGoToDistrict(activeDistrict.slug)}
              className="assam-inspect-action-btn"
            >
              <span>{dt.exploreDistrict}</span>
              <ArrowRight size={14} />
            </button>
          </div>
        )}
      </div>

      {/* Map Legend Footer */}
      <div className="assam-map-footer">
        <div className="assam-legend-row">
          <div className="assam-legend-item">
            <span className="legend-dot" style={{ background: '#059669' }} />
            <span>{dt.upperAssam}</span>
          </div>
          <div className="assam-legend-item">
            <span className="legend-dot" style={{ background: '#EF4444' }} />
            <span>{dt.lowerAssam}</span>
          </div>
          <div className="assam-legend-item">
            <span className="legend-dot" style={{ background: '#6366F1' }} />
            <span>{dt.bodoland}</span>
          </div>
          <div className="assam-legend-item">
            <span className="legend-dot" style={{ background: '#0D9488' }} />
            <span>{dt.northAssam}</span>
          </div>
          <div className="assam-legend-item">
            <span className="legend-dot" style={{ background: '#D97706' }} />
            <span>{dt.centralAssam}</span>
          </div>
          <div className="assam-legend-item">
            <span className="legend-dot" style={{ background: '#16A34A' }} />
            <span>{dt.hillsKarbi}</span>
          </div>
          <div className="assam-legend-item">
            <span className="legend-dot" style={{ background: '#8B5CF6' }} />
            <span>{dt.barakValley}</span>
          </div>
          <div className="assam-legend-item">
            <span className="legend-line" style={{ background: '#0284C7' }} />
            <span>{language === 'as' ? 'ব্ৰহ্মপুত্ৰ নদী' : language === 'hi' ? 'ब्रह्मपुत्र नदी' : 'Brahmaputra River'}</span>
          </div>
          <div className="assam-legend-item">
            <span className="legend-line" style={{ background: '#6366F1' }} />
            <span>{language === 'as' ? 'বৰাক নদী' : language === 'hi' ? 'बराक नदी' : 'Barak River'}</span>
          </div>
        </div>
      </div>
    </div>
  );
};
